/**
 * Kind of a process event.
 */
export enum ProcessEventKind {
    /**
     * stdout bytes.
     */
    Stdout,
    /**
     * stderr bytes.
     */
    Stderr,
    /**
     * PTY bytes.
     */
    Pty,
    /**
     * The process ended (always last).
     */
    Exit
}

const FfiConverterTypeProcessEventKind = (() => {
    const ordinalConverter = FfiConverterInt32;
    type TypeName = ProcessEventKind;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        read(from: RustBuffer): TypeName {
            switch (ordinalConverter.read(from)) {
                case 1: return ProcessEventKind.Stdout;
                case 2: return ProcessEventKind.Stderr;
                case 3: return ProcessEventKind.Pty;
                case 4: return ProcessEventKind.Exit;
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        write(value: TypeName, into: RustBuffer): void {
            switch (value) {
                case ProcessEventKind.Stdout: return ordinalConverter.write(1, into);
                case ProcessEventKind.Stderr: return ordinalConverter.write(2, into);
                case ProcessEventKind.Pty: return ordinalConverter.write(3, into);
                case ProcessEventKind.Exit: return ordinalConverter.write(4, into);
            }
        }
        allocationSize(value: TypeName): number {
            return ordinalConverter.allocationSize(0);
        }
    }
    return new FFIConverter();
})();

