/**
 * Screenshot encoding.
 */
export enum ImageFormat {
    /**
     * PNG.
     */
    Png,
    /**
     * JPEG.
     */
    Jpeg,
    /**
     * WebP.
     */
    Webp
}

const FfiConverterTypeImageFormat = (() => {
    const ordinalConverter = FfiConverterInt32;
    type TypeName = ImageFormat;
    class FFIConverter extends AbstractFfiConverterByteArray<TypeName> {
        read(from: RustBuffer): TypeName {
            switch (ordinalConverter.read(from)) {
                case 1: return ImageFormat.Png;
                case 2: return ImageFormat.Jpeg;
                case 3: return ImageFormat.Webp;
                default: throw new UniffiInternalError.UnexpectedEnumCase();
            }
        }
        write(value: TypeName, into: RustBuffer): void {
            switch (value) {
                case ImageFormat.Png: return ordinalConverter.write(1, into);
                case ImageFormat.Jpeg: return ordinalConverter.write(2, into);
                case ImageFormat.Webp: return ordinalConverter.write(3, into);
            }
        }
        allocationSize(value: TypeName): number {
            return ordinalConverter.allocationSize(0);
        }
    }
    return new FFIConverter();
})();

